package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.uiapi.*;
import dev.tacticalcombat.rules.srd.*;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;

/** Shared formatted D&D sheet. All mutable controls delegate to existing acknowledged operations. */
public final class CharacterSheetUi {
    public interface Actions {
        boolean healthEditable(); boolean trackable(String section);
        void health(String key,int delta); void track(RpgRecords.Change change);
        void inspect(FeatureReference.Entry entry); void encounters(); boolean campaign();
    }
    private CharacterSheetUi() {}
    public static List<UiLayout.Rect> columns(int width,int y,int count,int height){int cols=width>=620?Math.min(count,3):width>=300?Math.min(count,2):1,gap=8,cw=(width-12-gap*(cols-1))/cols;var out=new ArrayList<UiLayout.Rect>();for(int i=0;i<count;i++)out.add(new UiLayout.Rect(6+i%cols*(cw+gap),y+i/cols*(height+gap),cw,height));return List.copyOf(out);}
    public static void build(CharacterCanvas pane,JsonObject snapshot,boolean library,Actions actions,JsonObject validation,JsonObject encounter){int x=6,w=pane.getWidth()-12,y=6;var sheet=snapshot.getAsJsonObject("sheet");var identity=SheetSections.read(sheet,"identity");var xp=DashboardModel.xp(sheet);
        var font=net.minecraft.client.MinecraftClient.getInstance().textRenderer;String characterName=text(snapshot,"name");int nameHeight=Math.max(28,font.getTextHandler().wrapLines(characterName,w-48,net.minecraft.text.Style.EMPTY).size()*12);var identityRows=new ArrayList<String>();identityRows.add("Race: "+shown(text(identity,"species")));identityRows.add("Class: "+shown(text(identity,"characterClass"))+(text(identity,"subclass").isBlank()?"":" / "+text(identity,"subclass"))+" · Level "+xp.level());identityRows.add("Age: "+shown(text(identity,"age"))+"   Height: "+shown(text(identity,"height")));identityRows.add("Alignment: "+shown(text(identity,"alignment")));if(!text(identity,"background").isBlank())identityRows.add("Background: "+text(identity,"background"));int rowHeight=identityRows.stream().mapToInt(line->font.getTextHandler().wrapLines(line,w-16,net.minecraft.text.Style.EMPTY).size()*12).sum(),identityHeight=25+nameHeight+rowHeight+10;pane.panel("Character",x,y,w,identityHeight);pane.skinHead(library?"":text(snapshot,"owner"),x+8,y+24,24);pane.wrapped(characterName,x+40,y+25,w-48,RpgTheme.GOLD);int iy=y+25+nameHeight;for(String line:identityRows){pane.wrapped(line,x+8,iy,w-16,RpgTheme.TEXT);iy+=font.getTextHandler().wrapLines(line,w-16,net.minecraft.text.Style.EMPTY).size()*12;}y+=identityHeight+8;
        var abilities=DashboardModel.abilities(snapshot);int cols=w>=620?6:w>=300?3:w>=210?2:1,cw=(w-(cols-1)*6)/cols;for(int i=0;i<abilities.size();i++){var a=abilities.get(i);int ax=x+i%cols*(cw+6),ay=y+i/cols*47;pane.panel("",ax,ay,cw,41);pane.icon(a.label().toLowerCase(Locale.ROOT),ax+5,ay+5,12);pane.label(AbilityWorkspace.NAMES.get(a.label().toLowerCase(Locale.ROOT)),ax+20,ay+7,cw-25,RpgTheme.GOLD);pane.label(a.value().split(" · ")[0],ax+8,ay+23,cw-16,RpgTheme.TEXT);}y+=((abilities.size()+cols-1)/cols)*47+4;
        var stats=DashboardModel.combat(snapshot,library);var rows=columns(pane.getWidth(),y,stats.size(),45);for(int i=0;i<stats.size();i++){var r=rows.get(i);var s=stats.get(i);pane.panel(s.label(),r.x(),r.y(),r.width(),r.height());pane.label(s.value(),r.x()+8,r.y()+25,r.width()-16,RpgTheme.TEXT);}if(!rows.isEmpty())y=rows.getLast().y()+53;
        if(actions!=null&&actions.healthEditable()){for(String key:List.of("hp","temporary_hp")){String title=key.equals("hp")?"HP":"Temporary HP";pane.control("health:"+key+":-",new RpgButton(x,y,26,19,"−","",()->actions.health(key,-1)).accessible("Decrease "+title));pane.control("health:"+key+":+",new RpgButton(x+30,y,26,19,"+","",()->actions.health(key,1)).accessible("Increase "+title));pane.label(title,x+62,y+5,w-62,RpgTheme.MUTED);y+=24;}}
        var trackers=SheetSections.read(sheet,"trackers");pane.panel("Inspiration & Death Saves",x,y,w,102);int ty=y+25;
        if(actions!=null){var inspire=pane.control("inspiration",new RpgButton(x+8,ty,w-16,19,flag(trackers,"inspiration")?"Inspiration: Yes":"Inspiration: No","",()->actions.track(new RpgRecords.Change(RpgRecords.Action.INSPIRATION,"trackers","",0,flag(trackers,"inspiration")?0:1))));inspire.active=actions.trackable("trackers");}else pane.label("Inspiration: "+(flag(trackers,"inspiration")?"Yes":"No"),x+8,ty,w-16,RpgTheme.TEXT);ty+=24;
        for(boolean success:List.of(true,false)){String key=success?"deathSuccesses":"deathFailures";int value=trackers.get(key).getAsInt();String title=success?"Successes":"Failures";pane.label(title,x+8,ty+5,Math.min(75,Math.max(62,w-80))-12,RpgTheme.MUTED);for(int i=1;i<=3;i++){int target=i;if(actions!=null){var pip=pane.control(key+i,new RpgButton(x+Math.min(87,Math.max(62,w-80))+(i-1)*24,ty,20,18,i<=value?"●":"○","",()->actions.track(new RpgRecords.Change(success?RpgRecords.Action.DEATH_SUCCESSES:RpgRecords.Action.DEATH_FAILURES,"trackers","",0,target==value?target-1:target))).accessible(title+" "+i));pip.active=actions.trackable("trackers");}else pane.label(i<=value?"●":"○",x+Math.min(87,Math.max(62,w-80))+(i-1)*24,ty+4,20,RpgTheme.TEXT);}ty+=22;}y+=110;
        pane.panel("Advancement",x,y,w,xp.mode().equals("XP")?57:43);pane.label(xp.label(),x+8,y+26,w-16,RpgTheme.TEXT);if(xp.mode().equals("XP"))pane.progress(x+8,y+43,w-16,xp.fraction());y+=xp.mode().equals("XP")?65:51;
        pane.panel("Combat & Actions",x,y,w,34);pane.label("Supported attacks use the existing encounter controls.",x+8,y+22,w-16,RpgTheme.MUTED);y+=42;
        try{var data=SrdAuthoring.data(sheet);var weapons=new LinkedHashSet<String>();weapons.add("UNARMED");for(var entry:array(data,"weapons"))weapons.add(entry.getAsString().toUpperCase(Locale.ROOT));for(String name:weapons){var weapon=SrdEquipment.Weapon.valueOf(name);String damage=weapon.dice==0?Integer.toString(weapon.flat):weapon.dice+"d"+weapon.sides;pane.label(name.replace('_',' ')+" · base "+damage+" "+weapon.damageType.name().toLowerCase(Locale.ROOT)+(weapon.ranged?" · "+weapon.normalRangeFeet+" / "+weapon.longRangeFeet+" ft":""),x+8,y,w-16,RpgTheme.TEXT);y+=15;}if(encounter!=null&&!text(snapshot,"bound").isBlank()&&text(snapshot,"bound").equals(text(encounter,"active"))){pane.label("Current turn: action "+(flag(encounter,"actionUsed")?"spent":"available")+" · movement "+text(encounter,"remainingFeet")+" ft",x+8,y,w-16,RpgTheme.GOLD);y+=16;}for(String key:List.of("arrows","bolts","daggers"))if(data.has(key)){pane.label(key+": "+text(data,key),x+8,y,w-16,RpgTheme.MUTED);y+=14;}pane.label("Armor: "+text(data,"armor")+(flag(data,"shield")?" + shield":""),x+8,y,w-16,RpgTheme.TEXT);y+=19;}catch(RuntimeException unsupported){pane.label("Attacks follow this character's supported rules profile.",x+8,y,w-16,RpgTheme.MUTED);y+=18;}
        if(actions!=null&&actions.campaign()){pane.control("encounters",new RpgButton(x,y,w,19,"Open encounter controls","",actions::encounters));y+=26;}
        for(String key:List.of("resistances","immunities","vulnerabilities","armor_proficiencies","weapon_proficiencies")){try{var data=SrdAuthoring.data(sheet);pane.label(label(key)+": "+join(data,key),x+8,y,w-16,RpgTheme.TEXT);y+=15;}catch(RuntimeException ignored){}}
        pane.panel("Hit Dice & Resources",x,y,w,27);y+=34;int exhaustion=trackers.get("exhaustion").getAsInt();pane.label("Exhaustion: "+exhaustion,x+8,y+5,w-85,RpgTheme.TEXT);if(actions!=null){for(int delta:List.of(-1,1)){var control=pane.control("exhaustion:"+delta,new RpgButton(x+w-62+(delta<0?0:30),y,26,19,delta<0?"−":"+","",()->actions.track(new RpgRecords.Change(RpgRecords.Action.EXHAUSTION,"trackers","",0,Math.clamp(exhaustion+delta,0,6)))));control.active=actions.trackable("trackers");}}y+=27;
        int poolIndex=0;for(var raw:array(trackers,"hitDice")){var die=raw.getAsJsonObject();int index=poolIndex++,current=die.get("current").getAsInt(),maximum=die.get("maximum").getAsInt();pane.label("Hit Dice d"+text(die,"sides"),x+8,y,w-16,RpgTheme.GOLD);pane.label(current+" / "+maximum,x+8,y+20,w-80,RpgTheme.TEXT);if(actions!=null){for(int delta:List.of(-1,1)){var control=pane.control("hitdice:"+index+":"+delta,new RpgButton(x+w-62+(delta<0?0:30),y+16,26,19,delta<0?"−":"+","",()->actions.track(new RpgRecords.Change(RpgRecords.Action.HIT_DICE,"trackers","",index,Math.clamp(current+delta,0,maximum)))));control.active=actions.trackable("trackers");}}y+=42;}
        for(var raw:array(trackers,"resources")){var pool=raw.getAsJsonObject();String id=text(pool,"id");int current=pool.get("current").getAsInt(),maximum=pool.get("maximum").getAsInt();pane.label(text(pool,"name"),x+8,y,w-16,RpgTheme.GOLD);pane.label(current+" / "+maximum,x+8,y+20,w-80,RpgTheme.TEXT);if(actions!=null){for(int delta:List.of(-1,1)){var control=pane.control("pool:"+id+":"+delta,new RpgButton(x+w-62+(delta<0?0:30),y+16,26,19,delta<0?"−":"+","",()->actions.track(new RpgRecords.Change(RpgRecords.Action.RESOURCE,"trackers",id,0,Math.clamp(current+delta,0,maximum)))));control.active=actions.trackable("trackers")&&text(pool,"status").equals("MANUAL");}}y+=42;}
        var features=SheetSections.read(sheet,"features");pane.panel("Sheet Conditions & Features",x,y,w,27);y+=34;for(var raw:array(features,"entries").asList().stream().limit(6).toList()){var f=raw.getAsJsonObject();if(actions!=null){CreatorWorkspace.feature(pane,FeatureReference.recorded(f),x,y,w,actions::inspect);y+=22;}else{pane.label(text(f,"name")+" · "+text(f,"kind").toLowerCase(Locale.ROOT),x+8,y,w-16,RpgTheme.TEXT);y+=15;}}if(array(features,"entries").size()>6){pane.label("More entries on the Features page",x+8,y,w-16,RpgTheme.MUTED);y+=18;}if(array(features,"entries").isEmpty()){pane.label("No conditions or features added",x+8,y,w-16,RpgTheme.MUTED);y+=20;}
        pane.panel("Equipment Summary",x,y,w,27);y+=34;var inventory=SheetSections.read(sheet,"inventory");for(var e:InventoryModel.entries(inventory,InventoryModel.Category.ALL,"").stream().limit(5).toList()){pane.label(e.label()+" × "+e.quantity()+" · "+(e.equipped()?"Equipped":"Carried"),x+8,y,w-16,RpgTheme.TEXT);y+=16;}if(array(inventory,"items").size()>5){pane.label((array(inventory,"items").size()-5)+" more entries in Inventory & Equipment",x+8,y,w-16,RpgTheme.MUTED);y+=18;}if(array(inventory,"items").isEmpty()){pane.label("No equipment added",x+8,y,w-16,RpgTheme.MUTED);y+=20;}
        pane.panel("Proficiencies",x,y,w,27);y+=34;var prof=SheetSections.read(sheet,"proficiencies");for(String key:List.of("skills","saves","tools","languages","expertise")){String line=label(key)+": "+join(prof,key);pane.wrapped(line,x+8,y,w-16,RpgTheme.TEXT);y+=net.minecraft.client.MinecraftClient.getInstance().textRenderer.getTextHandler().wrapLines(line,w-16,net.minecraft.text.Style.EMPTY).size()*12+4;}
        if(validation!=null&&!array(validation,"errors").isEmpty()){pane.panel("Fix before finishing",x,y,w,27);y+=34;for(var raw:array(validation,"errors")){var issue=raw.getAsJsonObject();pane.label(CreatorFlow.errorStep(text(issue,"section")).title+": "+text(issue,"message"),x+8,y,w-16,RpgTheme.ERROR);y+=16;}}
    }
    private static String shown(String value){return value.isBlank()?"Not set":value;}
    private static String label(String key){return Character.toUpperCase(key.charAt(0))+key.substring(1).replace('_',' ');}
    private static String join(JsonObject obj,String key){var values=DashboardModel.strings(obj,key);return values.isEmpty()?"None":String.join(", ",values);}
}
